n_proto_MemberIdentity.signature:
// MemberIdentity 用统一记法拼一个成员身份：user:<name> / agent:<name>。
//
// kind 只认 IdentityKindUser / IdentityKindAgent；name 非空、无首尾空白、
// 不含分隔符 : 与空白字符。错误信息可行动（写清缺什么）。
func MemberIdentity(kind, name string) (string, error)

n_proto_ParseMemberIdentity.signature:
// ParseMemberIdentity 解出统一记法的 (kind, name)。空串、非统一记法前缀、
// 残缺名字都返回错误——fail-closed，绝不把残缺身份悄悄降级成别的东西。
func ParseMemberIdentity(raw string) (kind, name string, err error)

n_proto_validateMemberName.signature:
// validateMemberName 校验名字本体：非空、无首尾空白、不含冒号与空白字符。
// 名字是全系统唯一的「人是谁」锚，宽松会造出两个看起来一样的人。
func validateMemberName(name string) error

n_agentd_Server_resolveConsoleIdentity.signature:
// resolveConsoleIdentity 是本卡身份解析唯一入口（契约 §3「身份解析只在 agentd
// 一处」）：人名取配置 console_user，端戳取登录会话设备名；缺名 fail-closed。
//
// 参数 r 只用于取本次请求的登录会话（cookie 会话 id → store.Session.DeviceName）。
// 主令牌（CLI）请求 identity.session 为空，端戳留空——端戳缺失不拦门。
func (s *Server) resolveConsoleIdentity(r *http.Request) consoleIdentity

n_agentd_Server_handleIdentity.signature:
// handleIdentity 返回本请求的控制台身份（GET /api/identity，契约接缝 #4）。
//
// 这是控制台会话页/新建会话表单的数据源：owner 预填、落款显示、缺名可行动
// 提示。三个键恒出（无 omitempty）——前端要能区分「空串」与「后端没发这个
// 字段」（老 agentd）。本端点不落账、不改状态，读配置与会话行。
func (s *Server) handleIdentity(w http.ResponseWriter, r *http.Request)

n_cmd_sessionSendActor.signature:
// sessionSendActor 决议 session send 的发言 actor（B358.9 接缝 #5）。
//
// 三形态（互斥，调用方已保证 --agent 与席位对不并用、席位对已完整）：
//   - agentFlag 非空：主 agent 出示启动身份，编码为 agent:<启动身份>；名字不合法
//     即 fail-closed（可行动报错），绝不回落到别的脸。
//   - cliChanged：协调者席位 cli:<cli>#<session>（currentSeatIdentity）。
//   - 否则：ledgerActor()（CLI 审计 actor，人尺度）。
//
// 抽成独立函数是为了让「三形态决议 + fail-closed」可单测，不与账本打开耦合。
func sessionSendActor(agentFlag, cliFlag, sessionFlag string, cliChanged bool) (string, error)

n_agentd_sessionDeviceName.signature:
// sessionDeviceName 取本次请求登录会话登记的设备名（端戳，B358.9）。
//
// 端戳在鉴权中间件查会话行时随 identity 一次读出（server.go auth 处装填），
// 本函数不再二次查库——无新增调用边。无登录会话（主令牌）时为空串：端戳缺失
// 不拦门（少的是落款，不是权力）。
func sessionDeviceName(ctx context.Context) string
